def VTask.prev {α : Type u_1} [DecidableEq α] (l : List α) (x : α) (h : x ∈ l) : α :=
  let lastEl := l.getLast (List.ne_empty_of_mem h)
  let rec helper (current : List α) (hcurrent : x ∈ current) (prev : α) : α :=
    match current with
    | [] => absurd hcurrent (by simp)
    | hd :: tl =>
      match Decidable.decEq hd x with
      | isTrue _  => prev
      | isFalse h2 => helper tl (List.mem_tail hcurrent h2) hd
  helper l h lastEl
